def train_model(train_loader, epochs=5):
    for epoch in range(epochs):
        for images, labels in train_loader:
            images, labels = images.cuda(), labels.float().cuda()
            optimizer.zero_grad()
            preds = model(images)
            loss = loss_fn(preds, labels)
            loss.backward()
            optimizer.step()
        print(f"Epoch {epoch}, loss: {loss.item()}")
    return model

