import albumentations as A
from albumentations.pytorch import ToTensorV2

test_conditions = {
    "Clean": A.Compose([
        A.Resize(224, 224),
        A.Normalize(mean=(0.48145466, 0.4578275, 0.40821073), std=(0.26862954, 0.26130258, 0.27577711)),
        ToTensorV2()
    ]),
    "JPEG q30": A.Compose([
        A.Resize(224, 224),
        A.ImageCompression(quality_lower=30, quality_upper=30, p=1.0),
        A.Normalize(mean=(0.48145466, 0.4578275, 0.40821073), std=(0.26862954, 0.26130258, 0.27577711)),
        ToTensorV2()
    ]),
    "Blur σ=2": A.Compose([
        A.Resize(224, 224),
        A.GaussianBlur(sigma_limit=(2.0, 2.0), p=1.0),
        A.Normalize(mean=(0.48145466, 0.4578275, 0.40821073), std=(0.26862954, 0.26130258, 0.27577711)),
        ToTensorV2()
    ]),
    "Crop 80%": A.Compose([
        A.Resize(224, 224),
        A.RandomResizedCrop(height=224, width=224, scale=(0.8, 0.8), p=1.0),
        A.Normalize(mean=(0.48145466, 0.4578275, 0.40821073), std=(0.26862954, 0.26130258, 0.27577711)),
        ToTensorV2()
    ]),
}

