import sys
sys.path.append('/content/Centaurus/aigc-detection3')
from eval.evaluate import evaluate

import numpy as np

def wrap_transform(transform):
    def wrapped(img):
        return transform(image=np.array(img))['image']
    return wrapped

test_conditions_wrapped = {name: wrap_transform(t) for name, t in test_conditions.items()}

model = FakeDetector(clip_model)
model.load_state_dict(torch.load("/content/drive/MyDrive/model_plain.pt"))
model = model.cuda().eval()

results_plain = {}
for name, transform in test_conditions_wrapped.items():
    val_dataset = ImageDataset(val_paths, val_labels, transform=transform)
    val_loader = DataLoader(val_dataset, batch_size=32)
    acc, auc = evaluate(model, val_loader)
    results_plain[name] = {"accuracy": round(acc*100, 2), "auc": round(auc, 4)}

print(results_plain)

with open('results_plain.json', 'w') as f:
    json.dump(results_plain, f, indent=2)

files.download('results_plain.json')

model = FakeDetector(clip_model)
model.load_state_dict(torch.load("/content/drive/MyDrive/model_augmented.pt"))
model = model.cuda().eval()

results_augmented = {}
for name, transform in test_conditions_wrapped.items():
    val_dataset = ImageDataset(val_paths, val_labels, transform=transform)
    val_loader = DataLoader(val_dataset, batch_size=32)
    acc, auc = evaluate(model, val_loader)
    results_augmented[name] = {"accuracy": round(acc*100, 2), "auc": round(auc, 4)}

print(results_augmented)

combined = {"plain": results_plain, "augmented": results_augmented}

with open('robustness_recheck.json', 'w') as f:
    json.dump(combined, f, indent=2)

files.download('robustness_recheck.json')

